from decimal import Decimal, ROUND_HALF_UP


def format_total(cents):
    if type(cents) is not int or cents < 0:
        raise ValueError("cents must be a nonnegative integer")
    amount = (Decimal(cents) / Decimal(100)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return f"USD {amount:.2f}"


def format_customer(name):
    normalized = " ".join(name.split())
    if not normalized:
        raise ValueError("customer name is required")
    return normalized


def heading(name, cents):
    return f"{format_customer(name)}: {format_total(cents)}"

